'use strict';

// MODULES //

var tape = require( 'tape' );
var empty = require( '@stdlib/array/empty' );
var Float32Array = require( '@stdlib/array/float32' );
var Int32Array = require( '@stdlib/array/int32' );
var zeros = require( '@stdlib/array/zeros' );
var isArray = require( '@stdlib/assert/is-array' );
var isFloat32Array = require( '@stdlib/assert/is-float32array' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var softmax = require( './../lib' );


// FUNCTIONS //

/**
* Returns the sum of an array.
*
* @private
* @param {Collection} x - input array
* @returns {number} sum
*/
function sum( x ) {
	var s;
	var i;

	s = 0.0;
	for ( i = 0; i < x.length; i++ ) {
		s += x[ i ];
	}
	return s;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof softmax, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a collection', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			softmax( value );
		};
	}
});

tape( 'the function throws an error if provided a first argument which does not have a supported data type', function test( t ) {
	var values;
	var i;

	values = [
		empty( 5, 'bool' )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			softmax( value );
		};
	}
});

tape( 'the function throws an error if provided a second argument which is not a plain object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			softmax( [ 1.0, 2.0, 3.0 ], value );
		};
	}
});

tape( 'the function throws an error if provided an invalid `dtype` option', function test( t ) {
	var values;
	var i;

	values = [
		'int32',
		'foo',
		'bar',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			softmax( [ 1.0, 2.0, 3.0 ], {
				'dtype': value
			});
		};
	}
});

tape( 'the function computes softmax values', function test( t ) {
	var out;

	out = softmax( [ 1.0, 2.0, 3.0 ] );
	t.strictEqual( isArray( out ), true, 'returns expected value' );
	t.ok( out[ 0 ] < out[ 1 ] && out[ 1 ] < out[ 2 ], 'returns expected value' );
	t.ok( sum( out ) > 0.99999999999999 && sum( out ) < 1.00000000000001, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying an output array data type', function test( t ) {
	var out;

	out = softmax( [ 1.0, 2.0, 3.0 ], {
		'dtype': 'float64'
	});
	t.strictEqual( isFloat64Array( out ), true, 'returns expected value' );

	out = softmax( [ 1.0, 2.0, 3.0 ], {
		'dtype': 'float32'
	});
	t.strictEqual( isFloat32Array( out ), true, 'returns expected value' );

	t.end();
});

tape( 'the function defaults to float32 output for float32 input', function test( t ) {
	var out;

	out = softmax( new Float32Array( [ 1.0, 2.0, 3.0 ] ) );
	t.strictEqual( isFloat32Array( out ), true, 'returns expected value' );
	t.end();
});

tape( 'the function defaults to float64 output for integer input arrays', function test( t ) {
	var out;

	out = softmax( new Int32Array( [ 1, 2, 3 ] ) );
	t.strictEqual( isFloat64Array( out ), true, 'returns expected value' );
	t.end();
});

tape( 'the function is numerically stable for large values', function test( t ) {
	var out;

	out = softmax( [ 1000.0, 1001.0 ] );
	t.ok( out[ 0 ] > 0.0 && out[ 0 ] < 1.0, 'returns expected value' );
	t.ok( out[ 1 ] > 0.0 && out[ 1 ] < 1.0, 'returns expected value' );
	t.ok( sum( out ) > 0.99999999999999 && sum( out ) < 1.00000000000001, 'returns expected value' );

	t.end();
});

tape( 'the function handles positive infinity by distributing mass among the infinite values', function test( t ) {
	var out;

	out = softmax( [ Infinity, 1.0, Infinity ] );
	t.strictEqual( out[ 0 ], 0.5, 'returns expected value' );
	t.strictEqual( out[ 1 ], 0.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 0.5, 'returns expected value' );

	t.end();
});

tape( 'the function handles all negative infinity values', function test( t ) {
	var out;

	out = softmax( [ -Infinity, -Infinity, -Infinity ] );
	t.strictEqual( out[ 0 ], 1.0/3.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 1.0/3.0, 'returns expected value' );
	t.strictEqual( out[ 2 ], 1.0/3.0, 'returns expected value' );

	t.end();
});

tape( 'if the input contains NaN, the function returns all NaN values', function test( t ) {
	var out;

	out = softmax( [ 1.0, NaN, 3.0 ] );
	t.strictEqual( isNaN( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isNaN( out[ 1 ] ), true, 'returns expected value' );
	t.strictEqual( isNaN( out[ 2 ] ), true, 'returns expected value' );

	t.end();
});

tape( 'the function has an `assign` method which throws an error if provided a first argument which is not a collection', function test( t ) {
	var values;
	var out;
	var i;

	out = zeros( 3, 'generic' );
	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			softmax.assign( value, out );
		};
	}
});

tape( 'the function has an `assign` method which throws an error if provided a second argument which is not a collection', function test( t ) {
	var values;
	var x;
	var i;

	x = [ 1.0, 2.0, 3.0 ];
	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			softmax.assign( x, value );
		};
	}
});

tape( 'the function has an `assign` method which throws an error when input and output arrays do not have equal lengths', function test( t ) {
	t.throws( badValue, RangeError, 'throws an error' );
	t.end();

	function badValue() {
		softmax.assign( [ 1.0, 2.0, 3.0 ], zeros( 2, 'generic' ) );
	}
});

tape( 'the function has an `assign` method which computes softmax values', function test( t ) {
	var out;
	var x;
	var v;

	x = [ 1.0, 2.0, 3.0 ];
	out = [ 0.0, 0.0, 0.0 ];

	v = softmax.assign( x, out );
	t.strictEqual( v, out, 'returns expected value' );
	t.ok( out[ 0 ] < out[ 1 ] && out[ 1 ] < out[ 2 ], 'returns expected value' );
	t.ok( sum( out ) > 0.99999999999999 && sum( out ) < 1.00000000000001, 'returns expected value' );

	t.end();
});
